package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Explicit scalar-to-byte bridge. Vanilla redstone strength is never silently treated as binary. */
public class RedstoneByteEncoderBlock extends DirectionalDomainBlock{public RedstoneByteEncoderBlock(Properties p){super(p);}@Override public MapCodec<RedstoneByteEncoderBlock> codec(){return RedstoneEngineering.REDSTONE_BYTE_ENCODER_CODEC.value();}private void update(ServerLevel l,BlockPos p,BlockState s){int v=l.getSignal(inputPos(p,s),inputSide(s));InformationRuntime.write(l,"bus8_out",p,v,0,true,100);BlockPos out=outputPos(p,s);if(l.getBlockState(out).getBlock() instanceof EightBitDataBusBlock)DataBusNetwork.resolve(l,DataBusNetwork.collect(l,out));}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)update(sl,p,s);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block nb,BlockPos np,boolean m){if(l instanceof ServerLevel sl)update(sl,p,s);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Encoder: redstone 0-15 -> byte "+InformationRuntime.value(l,"bus8_out",p)),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
